import { spawn } from 'node:child_process';
import { createWriteStream } from 'node:fs';
import { mkdir, mkdtemp, readFile, writeFile, rename, stat, open } from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { setTimeout as delay } from 'node:timers/promises';
import { checkRtl, inspectVivado, launchSpec, killTree, runProcess } from './vivado.mjs';

// The model supplies RTL only. All Tcl commands below are generated by us;
// encoding words keeps spaces, brackets, dollars and Unicode out of Tcl syntax.
const word = value => `[encoding convertfrom utf-8 [binary decode hex ${Buffer.from(String(value)).toString('hex')}]]`;
const LIMIT = 8 * 1024 * 1024;
const JOB_HOST = fileURLToPath(new URL('./vivado-job.ps1', import.meta.url));
const windowsWord = value => '"' + value.replace(/(\\*)"/g, '$1$1\\"').replace(/(\\+)$/, '$1$1') + '"';
async function maybeRead(file) {
  try { return await readFile(file, 'utf8'); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
}

export function workerScript(directory) {
  return `set rtl_queue ${word(directory)}
set rtl_ready [open [file join $rtl_queue ready.tmp] w]
puts $rtl_ready [pid]
close $rtl_ready
file rename -force [file join $rtl_queue ready.tmp] [file join $rtl_queue ready]
while {![file exists [file join $rtl_queue stop]]} {
  if {[file exists [file join $rtl_queue request.tcl]]} {
    file rename -force [file join $rtl_queue request.tcl] [file join $rtl_queue running.tcl]
    source [file join $rtl_queue running.tcl]
    file delete [file join $rtl_queue running.tcl]
  }
  after 25 {set rtl_tick 1}
  vwait rtl_tick
}
exit 0
`;
}

export function synthesisRequest({ cwd, logPath, marker }) {
  return `cd ${word(cwd)}
set rtl_rc [catch {source ${word(path.join(cwd, 'synth.tcl'))}} rtl_error]
set rtl_errors [open ${word(marker + '.message')} w]
if {$rtl_rc} {puts $rtl_errors "ERROR: $rtl_error"}
close $rtl_errors
flush stdout
flush stderr
set rtl_done [open ${word(marker + '.tmp')} w]
puts $rtl_done $rtl_rc
close $rtl_done
file rename -force ${word(marker + '.tmp')} ${word(marker)}
`;
}

// A worker owns one process tree, starts lazily at the first synthesis, and
// shares only initialized Vivado state. Every request sources a fresh design.
export function createSynthesisWorker({ executionRoot, onEvent }) {
  let child, directory, exit, closed = false, closePromise, busy = false;
  let log, logBytes = 0, logError, spawnError, recent = '';
  let commandText = '';
  const emit = event => { try { onEvent?.(event)?.catch?.(() => {}); } catch { /* Observers cannot change a verdict. */ } };
  async function close() {
    if (closePromise) return closePromise;
    closePromise = (async () => {
      closed = true;
      if (child) {
        // Kill while the launcher is alive: taskkill /T then includes helpers.
        // On Linux the process group can also survive its original leader.
        if (process.platform !== 'win32' && child.pid) {
          try { process.kill(-child.pid, 'SIGKILL'); } catch (error) { if (error.code !== 'ESRCH') throw error; }
        } else await killTree(child);
        let timer;
        try { await Promise.race([exit, new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('Persistent Vivado cleanup did not complete')), 5000); })]); }
        finally { clearTimeout(timer); }
      }
      if (log) await new Promise((resolve, reject) => {
        if (log.destroyed) return logError ? reject(new Error(logError)) : resolve();
        log.end(error => error ? reject(error) : resolve());
      });
    })();
    return closePromise;
  }
  async function execute(options) {
    if (closed) throw new Error('Persistent Vivado worker is closed');
    if (busy) throw new Error('Persistent Vivado worker is busy');
    busy = true;
    const deadline = AbortSignal.timeout(options.timeoutMs);
    const signal = options.signal ? AbortSignal.any([options.signal, deadline]) : deadline;
    try {
      signal.throwIfAborted();
      if (!child) {
        await mkdir(executionRoot, { recursive: true });
        directory = await mkdtemp(path.join(executionRoot, 'session-'));
        await writeFile(path.join(directory, 'worker.tcl'), workerScript(directory));
        let spec = launchSpec(options.executable, ['-mode', 'batch', '-nojournal', '-source', 'worker.tcl']);
        if (process.platform === 'win32') {
          const specFile = path.join(directory, 'job.json');
          const commandLine = windowsWord(spec.executable) + ' ' + (spec.windowsVerbatimArguments ? spec.args.join(' ') : spec.args.map(windowsWord).join(' '));
          await writeFile(specFile, JSON.stringify({ executable: spec.executable, commandLine, directory }));
          spec = { executable: path.join(process.env.SystemRoot ?? 'C:\\Windows', 'System32/WindowsPowerShell/v1.0/powershell.exe'),
            args: ['-NoLogo', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', JOB_HOST, '-SpecFile', specFile], windowsVerbatimArguments: false };
        }
        log = createWriteStream(path.join(directory, 'session.log'));
        log.on('error', error => { logError = error.message; });
        child = spawn(spec.executable, spec.args, { cwd: directory, windowsHide: true, shell: false,
          windowsVerbatimArguments: spec.windowsVerbatimArguments, detached: process.platform !== 'win32', stdio: ['ignore', 'pipe', 'pipe'] });
        const collect = chunk => {
          recent = (recent + chunk.toString('utf8')).slice(-32768);
          commandText = (commandText + chunk.toString('utf8')).slice(-LIMIT);
          if (logBytes < LIMIT) { const part = chunk.subarray(0, LIMIT - logBytes); log.write(part); logBytes += part.length; }
        };
        child.stdout.on('data', collect); child.stderr.on('data', collect);
        child.on('error', error => { spawnError = error.message; });
        exit = new Promise(resolve => child.once('close', resolve));
        emit({ type: 'persistent_session_start', launcherPid: child.pid, directory });
        while (await maybeRead(path.join(directory, 'ready')) === undefined) {
          signal.throwIfAborted();
          if (spawnError || child.exitCode !== null || child.signalCode !== null) throw new Error(spawnError || 'Vivado exited before session initialization: ' + recent);
          await delay(25, undefined, { signal });
        }
        const pid = Number((await readFile(path.join(directory, 'ready'), 'utf8')).trim());
        if (!Number.isSafeInteger(pid) || pid < 1) throw new Error('Invalid persistent Vivado ready marker');
        emit({ type: 'persistent_session_ready', launcherPid: child.pid, vivadoPid: pid, directory });
      }
      if (spawnError || child.exitCode !== null || child.signalCode !== null) throw new Error(spawnError || 'Persistent Vivado exited unexpectedly: ' + recent);
      const marker = path.join(options.cwd, 'persistent-' + randomUUID() + '.done');
      const nativeLog = path.join(directory, 'vivado.log');
      const offset = (await stat(nativeLog)).size;
      commandText = '';
      const script = synthesisRequest({ ...options, marker });
      await writeFile(path.join(directory, 'request.tmp'), script);
      await rename(path.join(directory, 'request.tmp'), path.join(directory, 'request.tcl'));
      while (true) {
        signal.throwIfAborted();
        if (logError) throw new Error(logError);
        const done = await maybeRead(marker);
        if (done !== undefined) {
          if (!/^[01]\s*$/.test(done)) throw new Error('Invalid persistent synthesis completion marker');
          // Use only this command's native log slice and terminal output. The
          // atomic status is published after source finishes, never on queueing.
          const handle = await open(nativeLog, 'r');
          let text;
          try {
            const length = (await handle.stat()).size - offset;
            if (length < 0 || length > LIMIT) throw new Error('Invalid persistent synthesis log size');
            const buffer = Buffer.alloc(length);
            await handle.read(buffer, 0, length, offset);
            text = buffer.toString('utf8') + '\n' + commandText + '\n' + await readFile(marker + '.message', 'utf8');
          } finally { await handle.close(); }
          if (Number(done.trim()) === 0) {
            for (const name of ['post_synth.dcp', 'utilization.rpt']) {
              const artifact = await stat(path.join(options.cwd, name));
              if (!artifact.isFile() || artifact.size < 1) throw new Error('Missing fresh synthesis artifact: ' + name);
            }
          }
          await writeFile(options.logPath, text);
          return { exitCode: Number(done.trim()), text, cancelled: false, timedOut: false };
        }
        if (spawnError || child.exitCode !== null || child.signalCode !== null) throw new Error(spawnError || 'Vivado exited during synthesis: ' + recent);
        await delay(25, undefined, { signal });
      }
    } catch (error) {
      if (directory) await writeFile(options.logPath, commandText + '\n' + error.message).catch(() => {});
      await close();
      return { exitCode: null, text: recent, cancelled: Boolean(options.signal?.aborted), timedOut: !options.signal?.aborted && deadline.aborted,
        ...(!signal.aborted ? { spawnError: error.message } : {}) };
    } finally { busy = false; }
  }
  return { execute, close, get closed() { return closed; } };
}

export function createPersistentBackend({ config }) {
  let worker, identity, closed = false;
  const executionRoot = path.join(config.mcp.workspaceRoot, '.vivado-work');
  async function reset() { if (worker) { await worker.close(); worker = undefined; } }
  return {
    info: options => inspectVivado(config.vivado, options),
    async check(inputs) {
      if (closed) throw new Error('Persistent backend is closed');
      const next = JSON.stringify([inputs.task.id, inputs.task.top, inputs.task.clockPort, inputs.task.clockPeriodNs]);
      if (identity !== next) { await reset(); identity = next; }
      try {
        const result = await checkRtl({ ...inputs, executionRoot, config: config.vivado, executor: async options => {
          if (options.tool !== 'vivado') return runProcess(options.executable, options.args, options);
          if (!worker || worker.closed) worker = createSynthesisWorker({ executionRoot, onEvent: inputs.onEvent });
          return worker.execute(options);
        } });
        if (inputs.signal?.aborted || result.stages.some(stage => ['timeout', 'error'].includes(stage.status))) await reset();
        return result;
      } catch (error) { await reset(); throw error; }
    },
    async close() { closed = true; await reset(); },
  };
}
